sourceAnchors.selector:
@keyframes kp-screen-in {
  from {
    transform: translateY(8px);
  }
  to {
    transform: translateY(0);
  }
}

.av-surface,
.av-public-panel,
.av-stat-strip {
  border: 1px solid var(--av-color-border);
  border-radius: var(--av-radius-panel);
  background: var(--av-color-surface);
  box-shadow: var(--av-shadow-xs);
}

.av-eyebrow {
  color: var(--av-color-text-subtle);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  line-height: 1.25;
  text-transform: uppercase;
}
